class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_index, best_time = events[0][0], events[0][1]
        last = events[0][1]
        for i in range(1, len(events)):
            index, time = events[i]
            duration = time - last
            if duration > best_time or (duration == best_time and index < best_index):
                best_index, best_time = index, duration
                last = time
        return best_index

from typing import List


class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        longest = {events[0][0]: events[0][1]}
        for i in range(1, len(events)):
            index, time = events[i]
            longest[index] = time - events[i - 1][1]
        return min(longest, key=lambda b: (-longest[b], b))

